import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])

    max_ones = (n * n + n) // 2
    if k > max_ones:
        print("-1")
        return

    matrix = [[0] * n for _ in range(n)]

    for i in range(n):
        for j in range(i, n):
            if k == 0:
                break
            if i == j:
                if k > 0:
                    matrix[i][j] = 1
                    k -= 1
            else:
                if k >= 2:
                    matrix[i][j] = 1
                    matrix[j][i] = 1
                    k -= 2
                elif k == 1:
                    pass

        if k == 0:
            break

    if k > 0:
        print("-1")
        return

    for row in matrix:
        print(" ".join(map(str, row)))

if __name__ == "__main__":
    solve()
